import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"橫渠易說 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"橫渠易說 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/hengqu/063.md","filePath":"classics/hengqu/063.md"}'),l={name:"classics/hengqu/063.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><h3 id="彖曰-中孚-柔在內而剛得中-說而巽-孚乃化邦也。-豚魚吉-信及豚魚也-利涉大川-乘木舟處也。中孚以利貞-乃應乎天也。" tabindex="-1">彖曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。“豚魚吉”，信及豚魚也；“利涉大川”，乘木舟處也。中孚以利貞，乃應乎天也。 <a class="header-anchor" href="#彖曰-中孚-柔在內而剛得中-說而巽-孚乃化邦也。-豚魚吉-信及豚魚也-利涉大川-乘木舟處也。中孚以利貞-乃應乎天也。" aria-label="Permalink to “彖曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。“豚魚吉”，信及豚魚也；“利涉大川”，乘木舟處也。中孚以利貞，乃應乎天也。”">​</a></h3><h3 id="象曰-澤上有風-中孚-君子以議獄緩死。" tabindex="-1">象曰：澤上有風，中孚，君子以議獄緩死。 <a class="header-anchor" href="#象曰-澤上有風-中孚-君子以議獄緩死。" aria-label="Permalink to “象曰：澤上有風，中孚，君子以議獄緩死。”">​</a></h3><p>中孚，上巽施之，下悅承之，其中必有感化而出焉者。蓋孚者覆乳之象，有必生之理，信且正，天之道也。</p><h3 id="初九-虞吉-有他不燕。-象曰-初九虞吉-志未變也。" tabindex="-1">初九，虞吉，有他不燕。 象曰：“初九虞吉”，志未變也。 <a class="header-anchor" href="#初九-虞吉-有他不燕。-象曰-初九虞吉-志未變也。" aria-label="Permalink to “初九，虞吉，有他不燕。 象曰：“初九虞吉”，志未變也。”">​</a></h3><p>為信之始，其信未孚，而志應在四，進有二三，剛柔之間，非以禮自防，使為眾所信，取悔之道也。故必防其萌，使志不亂，孚交如則威如乃吉。</p><h3 id="九二-鳴鶴在陰-其子和之。我有好爵-吾與爾靡之。-象曰-其子和之-中心願也。" tabindex="-1">九二，鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。 象曰：“其子和之”，中心願也。 <a class="header-anchor" href="#九二-鳴鶴在陰-其子和之。我有好爵-吾與爾靡之。-象曰-其子和之-中心願也。" aria-label="Permalink to “九二，鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。 象曰：“其子和之”，中心願也。”">​</a></h3><p>居中體巽，無所私系，德必有鄰，物願所歸，位以德致，為五所任，故曰“與爾靡之”。靡，偃也，順從之也。</p><h3 id="六三-得敵-或鼓或罷-或泣或歌。-象曰-或鼓或罷-位不當也。" tabindex="-1">六三，得敵，或鼓或罷，或泣或歌。 象曰：“或鼓或罷”，位不當也。 <a class="header-anchor" href="#六三-得敵-或鼓或罷-或泣或歌。-象曰-或鼓或罷-位不當也。" aria-label="Permalink to “六三，得敵，或鼓或罷，或泣或歌。 象曰：“或鼓或罷”，位不當也。”">​</a></h3><p>處非所安，物之所惡，剛而乘之，柔不相比，進退之際，惟敵是求，不恆其德，莫非己致。一作惟敵是得，故求之云云。</p><h3 id="六四-月幾望-馬匹亡-無咎。-象曰-馬匹亡-絕類上也。" tabindex="-1">六四，月幾望，馬匹亡，無咎。 象曰：“馬匹亡”，絕類上也。 <a class="header-anchor" href="#六四-月幾望-馬匹亡-無咎。-象曰-馬匹亡-絕類上也。" aria-label="Permalink to “六四，月幾望，馬匹亡，無咎。 象曰：“馬匹亡”，絕類上也。”">​</a></h3><p>誠以接物，體巽居柔，陰德之盛美者也。陰德盛美，物所願交，故必一其所應，絕類於上，使陰不疑陽，如月近望而不過於盈，可以無咎。一作免咎。</p><h3 id="九五-有孚攣如-無咎。-象曰-有孚攣如-位正當也。" tabindex="-1">九五，有孚攣如，無咎。 象曰：“有孚攣如”，位正當也。 <a class="header-anchor" href="#九五-有孚攣如-無咎。-象曰-有孚攣如-位正當也。" aria-label="Permalink to “九五，有孚攣如，無咎。 象曰：“有孚攣如”，位正當也。”">​</a></h3><p>處乎盛位而信不交物，未免於咎也。</p><h3 id="上九-翰音登於天-貞兇。-象曰-翰音登於天-何可長也" tabindex="-1">上九，翰音登於天，貞兇。 象曰：“翰音登於天”，何可長也! <a class="header-anchor" href="#上九-翰音登於天-貞兇。-象曰-翰音登於天-何可長也" aria-label="Permalink to “上九，翰音登於天，貞兇。 象曰：“翰音登於天”，何可長也!”">​</a></h3><p>處信之極，好居物上，信而無實，窮上必兇。一雲：將變而為小過也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
